INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 19, 'theory', 'Quiz: traits and generics');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 0, 'What happens in fn largest<T>(v: &[T]) -> &T if you compare two elements with > without adding a bound?', '["The program builds and crashes at run time", "The compiler substitutes PartialOrd itself", "A compile error: nothing says T is comparable", "The comparison is done by address"]', 2, 'Only the operations that the bound guarantees are allowed on a type parameter. T: PartialOrd tells the compiler that comparison is defined.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 1, 'What does monomorphization of a generic function do?', '["Creates a separate copy of the function for each type used, at build time", "Picks the right version at run time through a table", "Converts all types to one", "Turns off type checking"]', 0, 'There is no run-time overhead, calls are direct and can be inlined; the price is program size and build time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 2, 'What does a Box<dyn Shape> value on the stack consist of?', '["The whole shape data", "A single pointer to the data", "The type name as a string", "Two pointers: to the data and to the virtual method table (16 bytes)"]', 3, 'A fat pointer stores the data address and the vtable address, holding drop, size, alignment, and methods; the call is indirect.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 3, 'Which statement about the orphan rule is true?', '["You can implement any trait for any type", "You cannot implement a foreign trait for a foreign type: you must own at least one", "Traits can be implemented only in the same file", "The rule applies only to generics"]', 1, 'The rule stops two libraries from implementing the same foreign trait for the same foreign type in different ways and thus breaking compatibility.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 19, 4, 'How does the associated type Item in Iterator differ from a generic trait parameter?', '["It does not differ", "An associated type is visible only inside a function", "A type can have only one Iterator implementation, so the element type is single and is not repeated in every signature", "It is computed at run time"]', 2, 'For each implementation the associated type is fixed. A generic parameter would allow several implementations of one trait for one type.');
